INSERT INTO `kimai2_activities` VALUES (313,43,'Подготовка презентации для совета директоров','Собрать ключевые метрики и решения. Критерий: презентация ≤ 15 слайдов, чёткий план действий.',1,'#e359de',282393,48498,NULL,1,NULL,NULL,'2025-12-24 19:58:44'),(314,43,'Настройка сквозной аналитики','Свести данные из CRM/кабинетов в дашборд. Критерий: согласованная модель атрибуции и обновление ежедневно.',1,'#b3b962',790153,7960,NULL,1,NULL,NULL,'2025-12-24 19:58:44'),(315,43,'Разработка SOP по инцидентам','Описать шаги реагирования и эскалации. Критерий: одобрение ИБ и внедрение в runbook.',1,'#e48334',1677372,18857,NULL,1,NULL,NULL,'2025-12-24 19:58:44'),(316,43,'Оценка эффективности обучения','Собрать обратную связь, оценить прирост навыков. Критерий: CSAT ≥ 4,5/5, тестовый прогресс +20%.',1,'#bd455f',433816,16552,NULL,0,NULL,NULL,'2025-12-24 19:58:44'),(317,43,'Ведение технической документации','Обновить README, схемы архитектуры и runbook’и. Критерий: актуальные схемы и пошаговые инструкции в wiki.',1,'#dc1d23',1134137,32232,NULL,0,NULL,NULL,'2025-12-24 19:58:44'),(318,43,'Подготовка SOW для подрядчика','Описать объём работ, сроки и критерии приёмки. Критерий: согласование юристами и бизнесом.',0,'#804df6',835824,33535,NULL,0,NULL,NULL,'2025-12-24 19:58:44'),(319,44,'Проведение интервью с кандидатом','Провести структурированное интервью и оценку по компетенциям. Критерий: заполненный скоринг-лист и фидбек.',1,'#b13a27',1970372,42588,NULL,1,NULL,NULL,'2025-12-24 19:58:44'),(320,44,'Оптимизация карточек на маркетплейсе','Обновить фото, SEO-поля и атрибуты. Критерий: конверсия в заказ +2 п.п. за 30 дней.',1,'#d846d9',682744,23278,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(321,44,'Исследование конкурентов','Собрать ценовые предложения и уникальные преимущества 5–7 конкурентов. Критерий: сравнительная таблица и выводы для УТП.',1,'#479297',1145436,19572,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(322,44,'Исследование конкурентов','Собрать ценовые предложения и уникальные преимущества 5–7 конкурентов. Критерий: сравнительная таблица и выводы для УТП.',1,'#d4fd94',896063,39155,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(323,44,'Подготовка бренд-бука раздел «Digital»','Описать гайд по шрифтам, цветам, баннерам. Критерий: утверждение CMO, доступ в ЛК дизайна.',1,'#b84d74',1419942,21653,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(324,44,'Подготовка контент-плана','Составить темы на 8 недель и график публикаций. Критерий: 3 формата контента и KPI по вовлеченности.',0,'#e5c459',110423,6939,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(325,44,'Разработка тестов и кейсов','Подготовить 20 вопросов и 2 практических кейса. Критерий: валидность и проверка на пилоте.',1,'#202ec4',924049,23650,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(326,44,'Закупка оборудования через тендер','Подготовить ТЗ, критерии и провести сравнение. Критерий: экономия ≥ 5% от базовой цены.',1,'#f38bac',981358,16738,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(327,44,'Актуализация базы лидов в CRM','Очистить дубликаты, заполнить поля, вернуть «потерянных». Критерий: дубликаты < 2%, заполненность ключевых полей 95%.',1,'#2de38d',704237,16982,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(328,44,'Оценка эффективности обучения','Собрать обратную связь, оценить прирост навыков. Критерий: CSAT ≥ 4,5/5, тестовый прогресс +20%.',1,'#7bb1b6',426996,47986,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(329,44,'Оценка рисков проекта','Заполнить реестр рисков и план реакций. Критерий: статус обновлён, владельцы назначены.',1,'#e09b7b',1567156,24711,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(330,44,'Анализ причин брака (Ишикава]','Проработать топ-3 дефекта и причины. Критерий: снижение брака на 20% в следующем месяце.',0,'#8e521d',1323207,8223,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(331,44,'Настройка CI/CD пайплайна','Собрать и деплоить приложение через pipeline с автоматическими тестами. Критерий: время релиза ≤ 15 минут, автотесты > 80% проходят.',1,'#4012bd',1200096,9300,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(332,44,'Нагрузочное тестирование API','Провести тест до 2× пика трафика с профилированием узких мест. Критерий: устойчивость без деградации SLA и ошибок 5xx < 1%.',1,'#3e986a',1436251,21689,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(333,45,'Оптимизация маршрутов отгрузки','Пересчитать маршруты и загрузку ТС. Критерий: экономия логистических затрат 8%.',1,'#f4fe19',1600248,9063,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(334,45,'Обновление версий фреймворков','Перевести проект на LTS-версии фреймворка и зависимостей. Критерий: успешно собранный билд, тесты проходят, уязвимости «Critical» — 0.',1,'#91edc9',307039,39234,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(335,45,'Ретроспектива спринта','Провести встречу, собрать улучшения. Критерий: минимум 3 действия в бэклоге улучшений.',1,'#7e485d',372384,41277,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(336,45,'Еженедельный статус-отчёт','Подготовить отчёт по срокам, рискам и бюджетам. Критерий: отправка по графику и решения по блокерам.',1,'#194576',736514,17597,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(337,45,'Миграция статики на CDN','Вынести изображения/скрипты на CDN. Критерий: TTFB −20%, кеш-хиты > 90%.',1,'#9b170e',702555,27063,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(338,45,'Протоколирование встречи','Зафиксировать решения, сроки и ответственных. Критерий: рассылка протокола в день встречи.',0,'#e76ce6',240198,9585,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(339,45,'Обучение по комплаенсу','Провести тренинг и тестирование. Критерий: проходной балл ≥ 80%.',1,'#3e59a8',146995,26744,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(340,45,'Сводный бюджет на квартал','Собрать план доходов/расходов и платёжный календарь. Критерий: согласование с ЦФО.',1,'#4b322c',153657,31714,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(341,45,'Настройка маршрутных карт','Актуализировать операции и нормы времени. Критерий: согласование с технологом, выпуск без задержек.',1,'#0cac50',915916,32021,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(342,45,'Оптимизация маршрутов отгрузки','Пересчитать маршруты и загрузку ТС. Критерий: экономия логистических затрат 8%.',1,'#2144a6',1211975,45530,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(343,45,'A/B-тест заголовков лендинга','Сформировать 2–3 варианта и запустить тест. Критерий: статистическая значимость и uplift конверсии ≥ 5%.',1,'#791105',1133844,19813,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(344,45,'Реестр рисков и мероприятий','Обновить риски, вероятность/влияние и владельцев. Критерий: план реакций утверждён.',0,'#45641d',781197,24627,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(345,45,'Внутренний аудит процесса закупок','Проверить соответствие политике и лимитам. Критерий: отчёт с корректирующими действиями.',1,'#a09e2e',501584,8018,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(346,45,'Запуск партнерской программы','Подготовить оффер, правила и форму регистрации. Критерий: 10 партнёров воронки за месяц.',1,'#db0a1d',1716235,14952,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(347,46,'Настройка UTM-меток и целей','Единообразно промаркировать кампании и сверить цели в аналитике. Критерий: 100% трафика размечено, события фиксируются.',1,'#2b52d5',1881843,19716,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(348,46,'Нагрузочное тестирование API','Провести тест до 2× пика трафика с профилированием узких мест. Критерий: устойчивость без деградации SLA и ошибок 5xx < 1%.',1,'#ab8c16',1696712,13488,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(349,46,'Составление дорожной карты проекта','Разбить проект на этапы с датами и ответственными. Критерий: утверждённый Gantt с ресурсами.',1,'#3f139f',1749525,17523,NULL,0,NULL,NULL,'2025-12-24 19:58:45'),(350,46,'Внедрение мониторинга серверов','Подключить узлы к Prometheus/ELK и настроить алерты по CPU, RAM, дискам и ошибкам приложений. Критерий: дашборды и 8 ключевых алертов активны.',1,'#dafcc1',1569734,8952,NULL,1,NULL,NULL,'2025-12-24 19:58:45'),(351,47,'Настройка сквозной аналитики','Свести данные из CRM/кабинетов в дашборд. Критерий: согласованная модель атрибуции и обновление 