INSERT INTO `kimai2_invoice_templates` VALUES (1,'Основной (PDF)','Счёт','ИП Сидоров А.В.','наб. Чехова, 39\n596371 Чехов, Россия',10,20,'default','default','default','Благодарим за доверие к нашей компании! Мы всегда готовы оказать вам качественные услуги.\nПросим перевести общую сумму в течение 14 дней на указанный счёт. В назначении платежа обязательно укажите номер данного счёта.','336624571371','Телефон: (35222) 42-9694\nEmail: yrodionova@example.net\nСайт: www.komissarov.com','АО \"Альфа-Банк\"\nБИК: 0439160681\nКорр. счёт: 30165810906055029\nРасч. счёт: 40732810621630305','ru'),(2,'Счёт-фактура (HTML)','Компания','ООО \"РосРазработка\"','шоссе Ладыгина, 52\n286037 Сергиев Посад, Россия',30,20,'default','default','invoice','Благодарим за доверие к нашей компании! Мы всегда готовы оказать вам качественные услуги.\nПросим перевести общую сумму в течение 14 дней на указанный счёт. В назначении платежа обязательно укажите номер данного счёта.','135768576087','Телефон: (35222) 85-1299\nEmail: bsilov@example.com\nСайт: www.evdokimova.com','Банк ГПБ (АО)\nБИК: 0477014967\nКорр. счёт: 30101810441444410\nРасч. счёт: 40724810259176329','ru'),(3,'По дате услуги (PDF)','Счёт','ИП Сидоров А.В.','пр. Косиора, 23\n188455 Домодедово, Россия',14,20,'short','default','service-date','Спасибо за сотрудничество! Мы высоко ценим наши деловые отношения.\nПросим произвести оплату до указанной даты. Надеемся на дальнейшее плодотворное сотрудничество.','048332734201','Телефон: 8-800-732-8879\nEmail: tarasova.zanna@example.org\nСайт: www.samsonov.com','ПАО Сбербанк\nБИК: 0450604877\nКорр. счёт: 30195810741225843\nРасч. счёт: 40759810294000028','ru'),(4,'Табель времени (HTML)','Табель','ООО \"ТехСервис\"','проезд Ломоносова, 77\n986272 Воскресенск, Россия',7,20,'default','default','timesheet','Спасибо за сотрудничество! Мы высоко ценим наши деловые отношения.\nПросим произвести оплату до указанной даты. Надеемся на дальнейшее плодотворное сотрудничество.','788150161332','Телефон: +7 (922