INSERT INTO `kimai2_projects` VALUES (43,9,'Создание дата-марта продаж в DWH','P-15114938','Цель — сформировать единый витринный слой для аналитики продаж. Этапы: моделирование, ETL/ELT-пайплайны, валидация данных, дашборды. Срок — 10 недель; единая версия данных, время подготовки отчёта — минуты вместо часов.',1,82938,'#6b136c',6950893,'2026-01-19 00:00:00','2026-01-29 00:00:00','2026-05-01 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:44'),(44,9,'Программа повышения квалификации бухгалтеров','P-92739017','Цель — сократить ошибки и ускорить закрытие периода. Этапы: изменения законодательства, практикум 1С, кейсы, зачёт. Срок — 6 недель; ошибки в учёте −30%.',1,38903,'#db1483',4890626,'2025-12-31 00:00:00','2026-01-04 00:00:00','2026-03-28 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:44'),(45,9,'Внедрение MES в литейном производстве','P-69202698','Цель — обеспечить прослеживаемость и оперативный учёт. Этапы: моделирование процессов, интеграция с ERP/SCADA, пилот, тиражирование. Срок — 4 месяца; браковка −20%, время цикла −15%.',1,27355,'#aed031',1266181,'2025-09-29 00:00:00','2025-10-10 00:00:00','2026-01-02 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(46,9,'Школа руководителя для линейных менеджеров','P-01442731','Цель — развить управленческие навыки первого уровня. Этапы: планирование, делегирование, обратная связь, KPI. Срок — 8 недель; текучесть −10%, вовлечённость +8 п.п.',1,56794,'#3eca8e',7398640,'2025-10-12 00:00:00','2025-10-20 00:00:00','2026-01-05 00:00:00',NULL,NULL,0,NULL,1,NULL,'2025-12-24 19:58:45'),(47,9,'Внедрение сервиса электронного документооборота','P-39274915','Цель — перевести договорной контур в ЭДО с КЭП. Этапы: интеграции с 1С и ДБО, шаблоны, маршруты согласования, обучение пользователей. Срок — 2 месяца; сокращение цикла согласования на 40–60%.',1,35479,'#eb7980',9760795,'2025-07-22 00:00:00','2025-07-31 00:00:00','2025-12-21 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(48,10,'Канбан и супермаркеты комплектующих','P-10088630','Цель — сократить запасы и простои из-за отсутствия деталей. Этапы: расчёт контейнеров, разметка, сигналы, стандарты пополнения. Срок — 6 недель; запасы WIP −25%.',1,30588,'#416529',9194128,'2025-12-16 00:00:00','2025-12-26 00:00:00','2026-06-10 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(49,10,'Онлайн-курс по бережливому производству','P-46617798','Цель — распространить практики Lean на участках. Этапы: видео-модули, симуляции, кейсы, сертификация. Срок — 5 недель; выявленные улучшения — 30+ кайдзен-идей.',1,56944,'#707c43',1013415,'2025-08-18 00:00:00','2025-08-20 00:00:00','2025-09-27 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(50,10,'Оптимизация логистики и складских запасов','P-14388088','Цель — снизить расходы на логистику и склад. Этапы: маршрутизация, SLA перевозчиков, нормативы запасов, KPI. Срок — 9 недель; логистические затраты −10–15%.',1,62298,'#770080',5559670,'2026-01-02 00:00:00','2026-01-13 00:00:00','2026-02-16 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(51,10,'Оптимизация раскроя листового металла','P-52552526','Цель — снизить отходы при раскрое. Этапы: внедрение nesting-ПО, пересмотр карт раскроя, обучение операторов. Срок — 6 недель; экономия материала 8–12%.',1,70422,'#5fb3b3',8902600,'2025-09-27 00:00:00','2025-10-04 00:00:00','2025-11-24 00:00:00',NULL,NULL,1,NULL,1,NULL,'2025-12-24 19:58:45'),(52,10,'Оптимизация производительности PostgreSQL кластеров','P-05109111','Цель — повысить throughput и стабильность БД под пиковыми нагрузками. Этапы: профилирование, тюнинг параметров, реорганизация индексов, шардинг/репликация, тест нагрузок. Срок — 6 недель; рост TPS на 25–40%, p95-латентность −30%.',1,17740,'#515cf3',7259505,'2025-10-24 00:00:00','2025-11-01 00:00:00','2026-01-04 00:00:00',NULL,NULL,0,NULL,1,NULL,'2025-12-24 19:58:45'),(53,10,'Контент-стратегия и запуск корпоративного блога','P-68964160','Цель — сформировать органический трафик и лидогенерацию. Этапы: контент-план,